Schueler s = new Schueler();
s.Note = 2;
Console.WriteLine(s.Note);   // 2

s.Note = 9;                  // ungültig – wird abgelehnt
Console.WriteLine(s.Note);   // immer noch 2
// Ausgabe:
// 2
// Ungültige Note: 9
// 2

class Schueler
{
    private int note = 1;

    public int Note
    {
        get { return note; }
        set
        {
            if (value >= 1 && value <= 5)
            {
                note = value;
            }
            else
            {
                Console.WriteLine($"Ungültige Note: {value}");
            }
        }
    }
}

Artikel a = new Artikel();
a.Name = "Kebab";
a.Preis = 6;
Console.WriteLine($"{a.Name} kostet {a.Preis} Euro, Menge: {a.Menge}");
// Ausgabe: Kebab kostet 6 Euro, Menge: 1

class Artikel
{
    public string Name { get; set; } = "";
    public int Preis { get; set; }
    public int Menge { get; set; } = 1;
}

Konto k = new Konto("Mia");
k.Einzahlen(80);
k.Einzahlen(40);
Console.WriteLine($"{k.Inhaber}: {k.Guthaben} Euro");
Console.WriteLine($"Reich? {k.IstReich}");
// k.Guthaben = 1000000;   // Fehler! set ist privat
// Ausgabe:
// Mia: 120 Euro
// Reich? True

class Konto
{
    public string Inhaber { get; }
    public int Guthaben { get; private set; }

    // berechnete Property, nur get
    public bool IstReich => Guthaben >= 100;

    public Konto(string inhaber)
    {
        Inhaber = inhaber;
    }

    public void Einzahlen(int betrag)
    {
        if (betrag > 0)
        {
            Guthaben += betrag;
        }
    }
}

