Rechteck r = new Rechteck();
r.Breite = 3;
r.Hoehe = 4;
r.Breite = 6;
Console.WriteLine(r.Flaeche);

class Rechteck
{
    public int Breite { get; set; }
    public int Hoehe { get; set; }
    public int Flaeche => Breite * Hoehe;
}
